import { project, ui } from '@hozu/core'
import { zodAdapter } from '@hozu/schema-zod'
import { admin, archive, deleteAccount, home, login, notePage } from './routes.ts'
import { AdminBoard, ArchiveBoard, NotePage, NotesBoard } from './features/notes/views.ts'
import { notes } from './features/notes/feature.ts'
import { adminUsers, getNote } from './features/notes/model.ts'
import { me, Session } from './features/account/model.ts'
import { AccountBar, DeleteAccountPage, Login } from './features/account/views.ts'
import { account } from './features/account/feature.ts'
import { text as accountText } from './features/account/text.ts'
import { text as notesText } from './features/notes/text.ts'

export default project({
  schema: zodAdapter,
  session: Session,
  styles: new URL('./app.css', import.meta.url),
  app: new URL('./app.ts', import.meta.url),
  env: { files: ['.env', '.env.local'] },
  site: { url: 'http://localhost:3000', name: 'app', lang: 'en', locales: ['en', 'de'] },
